using System;using System.IO;using System.Media;
class AlertSoundTest {static int Main(){int plays=0;if(AlertSound.Deliver(false,()=>plays++)||plays!=0)throw new Exception("Mute ignored");if(!AlertSound.Deliver(true,()=>plays++)||plays!=1)throw new Exception("Enabled alert missing");if(AlertSound.Deliver(true,()=>{throw new IOException();}))throw new Exception("Audio error escaped isolation");using(var stream=typeof(AlertSound).Assembly.GetManifestResourceStream("Sentinel.Alert.wav")){if(stream==null)throw new Exception("Alert asset missing");using(var sound=new SoundPlayer(stream))sound.Load();}Console.WriteLine("PASS muted/enabled delivery, audio failure isolation, embedded WAV decoding; no sound played by test.");return 0;}}
